Controller result:
{"results": [{"id": "hp_doc_50a556d6f77b6a3874c348da6d89c7d97b881dffb96f757d7db7b9cdb48c5e56", "title": "Hennchata", "text": "The Hennchata is a cocktail consisting of Hennessy cognac and Mexican rice horchata agua fresca. It was invented by a restaurant owner in San Jose, California.", "score": 24.0658}, {"id": "hp_doc_5076c89b3bc106f6ede86232f662cfb5eddf19afba6e25a27ecb2a55a18e18c6", "title": "Otard", "text": "Otard, also known as Chateau de Cognac, is a French cognac house founded in 1795 by Jean-Baptiste Antoine Otard. The company has remained in the hands of the same family since its establishment. The firm is based in the Château des Valois (Château de Cognac), Cognac, Charente, its home since 1796.", "score": 16.9657}, {"id": "hp_doc_35c6d69d97c972d1f329ca6053d68df6b8328f42411bbc7d3506ef0ae2d40fd4", "title": "Hennessy", "text": "Jas Hennessy & Co., or more simply Hennessy, is a cognac house with headquarters in Cognac, France. Jas Hennessy & Co. sells about 50 million bottles a year worldwide, or more than 40 percent of the world’s cognac, making it the world's largest cognac producer. It is owned by Moët Hennessy, which is in turn owned by LVMH (66%) and Diageo (34%).", "score": 16.5407}], "remaining_searches": 2}
